mapper.update:
update MOD_CURVE_CONFIG
set CURVE_GROUP_CODE = #{curveGroupCode,jdbcType=VARCHAR},
CURVE_TYPE = #{curveType,jdbcType=VARCHAR},
ISSMOOTH = #{isSmooth,jdbcType=VARCHAR},
SMOOTHSECTION = #{smoothSection,jdbcType=VARCHAR},
UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where
SEC_TYPE_MODEL = #{secTypeModel,jdbcType=VARCHAR}
AND  SEC_DETAIL_TYPE_MODEL = #{secDetailTypeModel,jdbcType=VARCHAR}

    AND  FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

AND  SEQNO = #{seqNo,jdbcType=VARCHAR}

mapper.select:
select COUNT(1)
from MOD_CURVE_CONFIG
where 1=1

    AND  SEC_TYPE_MODEL = #{secTypeModel,jdbcType=VARCHAR}


    AND  SEC_DETAIL_TYPE_MODEL = #{secDetailTypeModel,jdbcType=VARCHAR}


    AND  FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

SELECT A.SEQNO AS seqNo, A.SEC_TYPE_MODEL AS secTypeModel, A.SEC_DETAIL_TYPE_MODEL AS secDetailTypeModel, A.FINPROD_ID AS finprodId, A.FINPROD_NAME AS finprodName, A.CURVE_GROUP_CODE AS curveGroupCode, A.CURVE_TYPE AS curveType, A.ISSMOOTH AS isSmooth, A.SMOOTHSECTION AS smoothSection, A.CREATE_USER AS createUser, A.CREATE_DEPT AS createDept, A.CREATE_TIME AS createTime, A.UPDATE_USER AS updateUser, A.UPDATE_TIME AS updateTime FROM MOD_CURVE_CONFIG A WHERE 1=1
AND SEC_TYPE_MODEL = #{secTypeModel,jdbcType=VARCHAR}
AND SEC_DETAIL_TYPE_MODEL = #{secDetailTypeModel,jdbcType=VARCHAR}
AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND SEQNO = #{seqNo,jdbcType=VARCHAR}

SELECT A.SEQNO AS seqNo, A.SEC_TYPE_MODEL AS secTypeModel, A.SEC_DETAIL_TYPE_MODEL AS secDetailTypeModel, A.FINPROD_ID AS finprodId, A.FINPROD_NAME AS finprodName, A.CURVE_GROUP_CODE AS curveGroupCode, A.CURVE_TYPE AS curveType, A.ISSMOOTH AS isSmooth, A.SMOOTHSECTION AS smoothSection, A.CREATE_USER AS createUser, A.CREATE_DEPT AS createDept, A.CREATE_TIME AS createTime, A.UPDATE_USER AS updateUser, A.UPDATE_TIME AS updateTime FROM MOD_CURVE_CONFIG A WHERE 1=1
AND SEC_TYPE_MODEL = #{secTypeModel,jdbcType=VARCHAR}
AND SEC_DETAIL_TYPE_MODEL = #{secDetailTypeModel,jdbcType=VARCHAR}
AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
